1: #!/usr/bin/env node
2: import fs from 'node:fs';
3: import path from 'node:path';
4: 
5: const root = path.resolve(process.cwd());
6: const tokensCss = fs.readFileSync(path.join(root, 'src/renderer/tokens.css'), 'utf8');
7: const stylesCss = fs.readFileSync(path.join(root, 'src/renderer/styles.css'), 'utf8');
8: 
9: const tokenMap = new Map();
10: const rootMatch = tokensCss.match(/:root\s*\{([\s\S]*?)\}/);
11: if (rootMatch) {
12:   for (const m of rootMatch[1].matchAll(/--([a-z0-9-]+)\s*:\s*([^;]+);/g)) {
13:     tokenMap.set('--' + m[1], m[2].trim());
14:   }
15: }
16: 
17: function resolveColor(value) {
18:   value = value.trim().replace(/;$/, '');
19:   const varMatch = value.match(/^var\((--[a-z0-9-]+)\)$/);
20:   if (varMatch) {
21:     const resolved = tokenMap.get(varMatch[1]);
22:     if (resolved) return resolveColor(resolved);
23:   }
24:   return value;
25: }
26: 
27: function hexToRgb(hex) {
28:   hex = hex.trim();
29:   if (hex.startsWith('#')) {
30:     let h = hex.slice(1);
31:     if (h.length === 3) {
32:       h = h.split('').map((c) => c + c).join('');
33:     }
34:     // Translucent colours are rejected until the check can composite them against the backdrop.
35:     if (h.length === 8) {
36:       const alpha = parseInt(h.slice(6), 16);
37:       if (alpha !== 255) return null;
38:       h = h.slice(0, 6);
39:     }
40:     if (h.length === 4) {
41:       const alpha = parseInt(h[3] + h[3], 16);
42:       if (alpha !== 255) return null;
43:       h = h.split('').map((c) => c + c).join('').slice(0, 6);
44:     }
45:     if (h.length !== 6) return null;
46:     if (!/^[0-9a-fA-F]{6}$/.test(h)) return null;
47:     const n = parseInt(h, 16);
48:     return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
49:   }
50:   const rgbMatch = hex.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)(?:\s*,\s*([\d.]+))?\s*\)/i);
51:   if (rgbMatch) {
52:     if (rgbMatch[4] !== undefined && Number.parseFloat(rgbMatch[4]) < 1) return null;
53:     return {
54:       r: Math.min(255, parseInt(rgbMatch[1], 10)),
55:       g: Math.min(255, parseInt(rgbMatch[2], 10)),
56:       b: Math.min(255, parseInt(rgbMatch[3], 10)),
57:     };
58:   }
59:   return null;
60: }
61: 
62: /** The last declaration wins inside one CSS rule, matching the browser's cascade. */
63: function lastDeclaration(block, property) {
64:   const pattern = new RegExp(`(?:^|;)\\s*${property}\\s*:\\s*([^;]+)`, 'g');
65:   let value = null;
66:   for (const match of block.matchAll(pattern)) value = match[1];
67:   return value;
68: }
69: 
70: function luminance({ r, g, b }) {
71:   const channel = (c) => {
72:     const s = c / 255;
73:     return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
74:   };
75:   return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
76: }
77: 
78: function contrast(fg, bg) {
79:   const l1 = luminance(fg);
80:   const l2 = luminance(bg);
81:   const light = Math.max(l1, l2);
82:   const dark = Math.min(l1, l2);
83:   return (light + 0.05) / (dark + 0.05);
84: }
85: 
86: const pairs = new Map();
87: const ruleRe = /([^{}]+)\{([^{}]*)\}/g;
88: let m;
89: while ((m = ruleRe.exec(stylesCss)) !== null) {
90:   const selector = m[1].trim();
91:   const block = m[2];
92:   const colorValue = lastDeclaration(block, 'color');
93:   const bgValue = lastDeclaration(block, 'background(?:-color)?');
94:   if (colorValue !== null && bgValue !== null) {
95:     const fg = resolveColor(colorValue);
96:     const bg = resolveColor(bgValue);
97:     const key = fg + '|' + bg;
98:     if (!pairs.has(key)) pairs.set(key, { fg, bg, selectors: [] });
99:     pairs.get(key).selectors.push(selector);
100:   }
101: }
102: 
103: const curated = [
104:   ['--text', '--bg'],
105:   ['--text', '--surface'],
106:   ['--muted', '--bg'],
107:   ['--muted', '--surface'],
108:   ['--accent', '--bg'],
109:   ['--accent', '--surface'],
110:   ['--ok', '--bg'],
111:   ['--ok', '--surface'],
112:   ['--warn', '--bg'],
113:   ['--warn', '--surface'],
114:   ['--danger', '--bg'],
115:   ['--danger', '--surface'],
116:   ['--focus', '--bg'],
117: ];
118: for (const [fgToken, bgToken] of curated) {
119:   const fg = tokenMap.get(fgToken);
120:   const bg = tokenMap.get(bgToken);
121:   if (fg && bg) {
122:     const key = fg + '|' + bg;
123:     if (!pairs.has(key)) pairs.set(key, { fg, bg, selectors: ['(token pair)'] });
124:   }
125: }
126: 
127: let failed = false;
128: console.log('ChessPulse contrast check (WCAG 2.2 AA)');
129: for (const { fg, bg, selectors } of pairs.values()) {
130:   const fgRgb = hexToRgb(fg);
131:   const bgRgb = hexToRgb(bg);
132:   if (fg === 'transparent' || bg === 'transparent') {
133:     continue;
134:   }
135:   if (!fgRgb || !bgRgb) {
136:     console.error(`Unsupported color format: ${fg} on ${bg}`);
137:     process.exitCode = 1;
138:     failed = true;
139:     continue;
140:   }
141:   const ratio = contrast(fgRgb, bgRgb);
142:   const ok = ratio >= 4.5;
143:   if (!ok) failed = true;
144:   const status = ok ? 'PASS' : 'FAIL';
145:   console.log(`${fg} on ${bg}  ${ratio.toFixed(2)}  ${status}  (${selectors.slice(0, 2).join(', ')})`);
146: }
147: 
148: if (failed) {
149:   console.error('\nContrast check FAILED: one or more pairs below 4.5:1.');
150:   process.exit(1);
151: }
152: console.log('\nContrast check PASS.');
153: process.exit(0);

