content.text:
select:focus-visible,
.strip:focus-visible,
.timeline-frame:focus-visible {
  outline: 2px solid var(--text);
  outline-offset: 2px;
}

.paste-banner {
  margin-top: 24px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
}

.paste-banner.tone-ok {
  border-color: var(--ok);
}

.paste-banner.tone-warn {
  border-color: var(--warn);
}

.banner-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
}

.status-pill,
.slot-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 12px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--muted);
}

.status-pill.tone-ok,
.slot-badge.tone-ok {
  border-color: var(--ok);
  color: var(--text);
}

.status-pill.tone-ok svg,
.slot-badge.tone-ok svg {
  color: var(--ok);
}

.status-pill.tone-warn,
.slot-badge.tone-warn {
  border-color: var(--warn);
  color: var(--text);
}

.status-pill.tone-danger,
.slot-badge.tone-danger {
  border-color: var(--danger);
  color: var(--text);
}

.banner-counts {
  color: var(--muted);
  font-family: ui-monospace, monospace;
  width: 100%;
  height: auto;
}

.game-band-even {
  fill: rgba(255, 255, 255, 0.025);
}

.game-band-odd {
  fill: rgba(0, 0, 0, 0.14);
}

.game-band-label {
  fill: var(--muted);
  font-family: ui-monospace, monospace;
  font-size: 11px;
}

.elevated-hatch-line {
  stroke: var(--accent);
  stroke-opacity: 0.22;
  stroke-width: 1;
}

.threshold-line {
  stroke: var(--accent);
  stroke-opacity: 0.7;
  stroke-dasharray: 4 4;
  stroke-width: 1;
}

.threshold-label {
  fill: var(--text);
  font-family: ui-monospace, monospace;
  font-size: 11px;
}
  stroke-linecap: round;
  stroke-linejoin: round;
}

.pulse-line.pulse-settled {
  stroke: var(--text);
  stroke-width: 1.75;
}

.pulse-line.pulse-elevated {
  stroke: var(--accent);
  stroke-width: 2.5;
}

.pulse-line.pulse-desaturated {
  stroke: var(--muted);
  stroke-opacity: 0.65;
  stroke-width: 1.5;
}

.pulse-dot.pulse-settled {
  fill: var(--text);
}

.pulse-dot.pulse-elevated {
  fill: var(--accent);
}

.pulse-dot.pulse-desaturated {
  fill: var(--muted);
  fill-opacity: 0.65;
.band-track-insufficient {
  stroke-dasharray: 4 4;
}

.band-fill-settled {
  fill: var(--text);
  fill-opacity: 0.78;
}

.band-fill-elevated {
  stroke: var(--accent);
  stroke-width: 1;
}

.band-elevated-bg {
  fill: var(--accent);
  fill-opacity: 0.28;
}

.band-elevated-hatch {
  stroke: var(--accent);
  stroke-width: 2;
}

.timeline-tables {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.table-wrap {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-family: ui-monospace, monospace;
  font-size: 12px;
}

.data-table caption {
  padding: 12px 16px 8px;
  text-align: left;
  color: var(--muted);
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 13px;
}

.data-table th,
.data-table td {
  padding: 8px 12px;
  text-align: left;
  border-top: 1px solid var(--line);
  color: var(--text);
}

.data-table th {
  color: var(--muted);
  font-weight: 500;
}

.data-table tr.row-elevated td:first-child {
  box-shadow: inset 3px 0 0 var(--accent);
}

.report-layout {
  display: flex;

