// Removed: `npm test` would run only named files and could pass while skipping suites.
import { run } from 'node:test';
import { spec } from 'node:test/reporters';
import { discoverTestFiles, testFileOfEvent } from './test-files.mjs';

const files = discoverTestFiles(process.cwd());
console.log(`Discovered ${files.length} test files.`);
if (files.length === 0) {
  console.error('No test files were found. The TypeScript build did not produce any.');
  process.exit(1);
}

const seenFiles = new Set();
let failures = 0;

const stream = run({ files });
stream.on('data', (event) => {
  const file = testFileOfEvent(event);
  if (file) seenFiles.add(file);
  if (event.type === 'test:fail') failures += 1;
});
stream.on('end', () => {
  const missing = files.filter((file) => !seenFiles.has(file));
  console.log(`Ran ${seenFiles.size} of ${files.length} test files.`);
  if (missing.length > 0) {
    console.error('Test files that registered no tests:');
    for (const file of missing) console.error(`  ${file}`);
    process.exitCode = 1;
  }
  if (failures > 0) process.exitCode = 1;
});
stream.compose(new spec()).pipe(process.stdout);
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { createElement } from 'react';
import type { Refusal } from '../shared/contracts.js';
import { mountDom } from './dom-harness.js';
import { Timeline } from './Timeline.js';

const refusal: Refusal = {
  ok: false,
  reason: 'low_coverage',
  measured: 20,
  threshold: 70,
  remedy: 'Sit facing the screen with a lamp in front of you.',
  trace: {
    startUs: 0,
    stopUs: 60_000_000,
    baselineBpm: 80,
    samples: [
      { tUs: 1_000_000, bpm: 78, confidence: 90, stable: true },
      { tUs: 2_000_000, bpm: 84, confidence: 88, stable: true },
    ],
  },
};

describe('Timeline legend and keyboard readout', () => {
  it('shows a text legend for every chart encoding', () => {
    const harness = mountDom(createElement(Timeline, { result: refusal }));
    const legend = harness.document.querySelector('[aria-label="Timeline key"]');
    assert.ok(legend);
    const text = legend.textContent ?? '';
    for (const label of ['Pulse', 'Move error (CPL)', 'Think time', 'Elevated pulse', 'Game ending']) {
      assert.match(text, new RegExp(label.replace(/[()]/g, '\\$&')));
    }
    assert.ok(harness.document.querySelector('.legend-hatch'));
    harness.unmount();
  });

  it('steps the sample readout with the arrow keys', () => {
    const harness = mountDom(createElement(Timeline, { result: refusal }));
    const frame = harness.document.querySelector('.timeline-frame');
    assert.ok(frame);
    harness.keyDown(frame, 'ArrowRight');
    harness.keyDown(frame, 'ArrowRight');
    const readout = harness.document.querySelector('.timeline-readout')?.textContent ?? '';
    assert.match(readout, /84(\.\d)? bpm/);
    harness.unmount();
  });
});
// What: a small DOM harness for renderer interaction tests.
// Why: the markup tests use `react-dom/server`, which cannot click, focus, or observe effects.
//      S57 adds jsdom so focus-return and keyboard behaviour can be asserted instead of reviewed.
// Removed: the focus claims in S49/S50 and H-27 would stay code-reviewed only.
import { JSDOM } from 'jsdom';
import { act, type ReactElement } from 'react';
import { createRoot } from 'react-dom/client';

export interface DomHarness {
  readonly document: JSDOM['window']['document'];
  readonly window: JSDOM['window'];
  readonly container: HTMLElement;
  render(element: ReactElement): void;
  click(element: Element): void;
  keyDown(element: Element, key: string): void;
  unmount(): void;
}

export function mountDom(element: ReactElement): DomHarness {
  const dom = new JSDOM('<!doctype html><html><body></body></html>', {
    pretendToBeVisual: true,
  });
  const scope = globalThis as unknown as Record<string, unknown>;
  scope.IS_REACT_ACT_ENVIRONMENT = true;
  scope.window = dom.window;
  scope.document = dom.window.document;
  scope.HTMLElement = dom.window.HTMLElement;
  scope.Node = dom.window.Node;
  scope.Event = dom.window.Event;
  scope.KeyboardEvent = dom.window.KeyboardEvent;
  scope.MouseEvent = dom.window.MouseEvent;

  const container = dom.window.document.createElement('div');
  dom.window.document.body.append(container);
  const root = createRoot(container);

  function render(next: ReactElement): void {
    act(() => {
      root.render(next);
    });

