  type SessionSummary,
  type ValidationMessage,
} from '../shared/contracts';
import {
  currentSessionId,
  flowReducer,
  initialFlowState,
  sensingHint,
  statusFor,
  type StatusLine,
} from '../shared/flow';
import { appErrorInfo } from '../shared/errors';
import {
  framingFromValidation,
  UNKNOWN_FRAMING,
} from '../shared/framing';
