```js
const mark = await page.evaluate(() => {
  const img = document.querySelector('.brand-mark');
  if (!img) return null;
  return { width: img.getBoundingClientRect().width, natural: img.naturalWidth };
});
assert.ok(mark && mark.width > 0 && mark.natural > 0, `home ${width}: brand mark did not render (CSP or missing asset)`);
if (width >= 960) {
  assert.ok(await page.locator('.board-tile').isVisible(), `home ${width}: 3D board tile is not visible`);
}
```

TypeScript? It's .mjs, no typing.

