          moves: [
            { san: 'e4', clockSec: 50 },
            { san: 'e5', clockSec: 40 },
            { san: 'Nf3' },
          ],
        }),
      ],
      withStop(120 * SEC),
      [],
      marksFor([60 * SEC], []),
