            {body ? <div className="stage-body">{body}</div> : null}
            {!body && stage.reason ? <p className="stage-reason">{reasonText(stage.state, stage.reason)}</p> : null}
          </section>
        );
      })}
    </section>
  );
}

/** The reason a stage is not showing its content, in the player's words. */
function reasonText(state: StageState, reason: StageReason): string {
  return state === 'unavailable' && reason === 'report_failed'
    ? COPY.stages.reasons.report_failed
    : COPY.stages.reasons[reason];
}

