/** What the player can change, per cause. The share comes from the session's own counts. */
const CAUSE_REMEDIES: Record<FramingCause, (share: number) => string> = {
  no_face: (share) =>
    `The face was out of frame for ${share}% of the session. Sit centred, with your upper chest in view.`,
  too_dark: (share) => `The room was too dark for ${share}% of the session. Put a lamp in front of you.`,
  too_far: (share) =>
    `You were too far from the camera for ${share}% of the session. Move closer until your face fills the frame.`,
  too_close: (share) =>
    `You were too close to the camera for ${share}% of the session. Move back until your face fits in the frame.`,
  motion: (share) => `There was too much movement for ${share}% of the session. Rest your arms on the desk.`,
  chest: (share) =>
    `Your chest was out of frame for ${share}% of the session. Sit back so your upper chest is in view.`,
  too_bright: (share) =>
