```ts
const dateUtc = Date.UTC(year, month-1, dayOfMonth);
const back = new Date(dateUtc);
if (back.getUTCFullYear() !== year || back.getUTCMonth() !== month-1 || back.getUTCDate() !== dayOfMonth) return 'bad';
