describe('stated clock zones', () => {
  const header = '[White "Ada"]\\n[Black "Nim"]\\n[Result "1-0"]\\n';

  it('reads the chess.com EndTime format with no EndDate', () => {
    const parsed = parsePgn(
      `${header}[EndTime "18:51:25 GMT+0000"]\\n\\n1. e4 1-0\\n`,
      0,
